const names={submitted:'ส่งเคสแล้ว',received:'ร้านรับเรื่อง',checking:'กำลังตรวจเช็ค',awaiting_approval:'รออนุมัติราคา',repairing:'กำลังซ่อม',ready:'พร้อมรับเครื่อง',closed:'ปิดเคส',cancelled:'ยกเลิก'};
let dataset=null;
function el(tag,text='',cls=''){const e=document.createElement(tag);e.textContent=text;e.className=cls;return e;}
async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json();}catch{throw new Error('หน้านี้ใช้ผ่าน backend local เท่านั้น');}if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'ตรวจข้อมูลที่กรอกอีกครั้ง');return d;}
const filter=document.querySelector('#admin-filter');filter.append(el('option','ทุกสถานะ'));filter.firstChild.value='all';for(const [k,v] of Object.entries(names)){const o=el('option',v);o.value=k;filter.append(o);}
function render(){const stats=document.querySelector('#admin-stats');stats.replaceChildren();for(const [k,v] of Object.entries(dataset.counts)){const box=el('div');box.append(el('strong',String(v)),el('span',names[k]));stats.append(box);}const list=document.querySelector('#admin-list');list.replaceChildren();const rows=dataset.cases.filter(c=>filter.value==='all'||c.status===filter.value);if(!rows.length)list.append(el('p','ไม่มีเคสในสถานะนี้','member-hint'));
 for(const c of rows){const row=el('article','','member-row');row.append(el('strong',c.reference+' · '+c.model+' · '+c.member_name),el('span',names[c.status],'status-badge'),el('p',c.issue));if(c.member_reply)row.append(el('p','ลูกค้าตอบกลับ: '+c.member_reply,'member-reply'));const detail=el('button','ประวัติสถานะและแชทที่แนบ','member-action');detail.onclick=async()=>{try{const d=await api('/admin/cases/'+c.id),box=el('div','','admin-detail');for(const e of d.events)box.append(el('p',(e.kind==='reply'?'ลูกค้าตอบ':e.kind==='note'?'ร้านแจ้ง ('+names[e.status]+')':names[e.status])+' · '+e.note+' · '+new Date(e.created*1000).toLocaleString('th-TH')));if(d.images?.length){box.append(el('strong','ภาพที่ลูกค้าส่งในแชท'));const kinds={device_or_screen:'ตัวเครื่อง/หน้าจอ',receipt_or_slip:'สลิป/หลักฐานการชำระ',unclear:'ภาพไม่ชัด'};const g=el('div','','admin-images');for(const im of d.images){const fig=el('figure'),img=el('img');img.src='/api/images/'+im.id;img.alt=kinds[im.kind]||'ภาพ';img.loading='lazy';fig.append(img,el('figcaption',(kinds[im.kind]||im.kind)+' · '+new Date(im.created*1000).toLocaleString('th-TH')+(im.observation?' · AI เห็น: '+im.observation.slice(0,160):'')));g.append(fig);}box.append(g);}if(d.messages.length)box.append(el('strong','บทสนทนาที่สมาชิกแนบ'));for(const m of d.messages)box.append(el('p',(m.role==='user'?'สมาชิก: ':'ผู้ช่วย: ')+m.content));row.querySelector('.admin-detail')?.remove();row.append(box);}catch(e){document.querySelector('#admin-error').textContent=e.message;}};row.append(detail);
   if(c.payment?.status==='paid')row.append(el('p','ชำระแล้ว '+Number(c.payment.amount).toLocaleString('th-TH')+' บาท (Stripe ทดสอบ)','quote-state'));
   if(c.quote)row.append(el('p','ใบเสนอ #'+c.quote.id+' · '+Number(c.quote.amount).toLocaleString('th-TH')+' บาท · '+({pending:'รอลูกค้าอนุมัติ',approved:'ลูกค้าอนุมัติแล้ว',rejected:'ลูกค้าปฏิเสธ',superseded:'ถูกแทนด้วยใบเสนอใหม่'}[c.quote.status])));
   const next=c.allowed_transitions||dataset.transitions[c.status];if(next.length){const form=el('form','','admin-case-form'),sl=el('label','สถานะถัดไป'),sel=el('select');for(const v of next){const o=el('option',v!==c.status?names[v]:v==='awaiting_approval'?'ส่งราคาใหม่ให้อนุมัติ':'คงสถานะเดิม · ส่งข้อความถึงลูกค้า');o.value=v;sel.append(o);}sl.append(sel);const nl=el('label','หมายเหตุ','note-field'),note=el('input');note.required=true;note.minLength=3;note.maxLength=1000;nl.append(note);const pl=el('label','ราคาเสนอ (บาท)'),price=el('input');price.type='number';price.min='0';price.max='1000000';price.step='.01';price.value=c.quoted_price??'';pl.append(price);const save=el('button','อัปเดตสถานะ');save.type='submit';const label=()=>{const only=sel.value===c.status&&c.status!=='awaiting_approval';save.textContent=only?'ส่งข้อความ':'อัปเดตสถานะ';price.disabled=only;};sel.onchange=label;label();form.append(sl,nl,pl,save);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await api('/admin/cases/'+c.id,'PATCH',{status:sel.value,note:note.value,quoted_price:price.disabled||price.value===''?null:Number(price.value)});await load();}catch(err){document.querySelector('#admin-error').textContent=err.message;save.disabled=false;}};row.append(form,aiButton(c,{sel,note,price}));}else row.append(aiButton(c,null));list.append(row);
 }}
const routeNames={price:'ราคา',shop_info:'ข้อมูลร้าน',advice:'คำแนะนำ',ambiguous:'กำกวม',case:'เคส',payment:'ชำระเงิน',greeting:'ทักทาย',out_of_scope:'นอกขอบเขต',unsafe:'ไม่ปลอดภัย',guard_card:'เลขบัตร',action:'ยืนยันรายการ'};
// AI advice only: "ใช้คำแนะนำ" fills the form; the admin still presses "อัปเดตสถานะ".
function aiButton(c,f){const b=el('button','AI ช่วยวิเคราะห์เคส','member-action ai-action');b.type='button';b.onclick=async()=>{b.disabled=true;b.textContent='AI กำลังวิเคราะห์…';try{const a=await api('/admin/cases/'+c.id+'/assist','POST'),box=el('div','','admin-ai');
 box.append(el('strong','สรุปโดย AI (ตรวจก่อนใช้)'),el('p',a.summary||'—'));
 if(a.hints?.length)box.append(el('p','ระบบสังเกต: '+a.hints.join(' · '),'member-hint'));
 if(a.missing_info?.length)box.append(el('p','ควรถามหรือตรวจเพิ่ม: '+a.missing_info.join(' · ')));
 if(a.quote_items?.length)box.append(el('p','รายการจากแค็ตตาล็อก: '+a.quote_items.map(i=>i.name+(i.price!=null?' '+Number(i.price).toLocaleString('th-TH')+' บาท':' (ประเมินแยก)')).join(' · ')));
 const sug=[a.suggested_status?'สถานะถัดไป: '+names[a.suggested_status]:'',a.suggested_price!=null?'ราคาเสนอ: '+Number(a.suggested_price).toLocaleString('th-TH')+' บาท':''].filter(Boolean).join(' · ');if(sug)box.append(el('p',sug));
 if(a.customer_note)box.append(el('p','ร่างหมายเหตุถึงลูกค้า: '+a.customer_note));
 if(a.reason)box.append(el('p','เหตุผล: '+a.reason,'member-hint'));
 for(const w of a.warnings||[])box.append(el('p','⚠ '+w,'admin-ai-warning'));
 if(f&&(a.suggested_status||a.customer_note)){const use=el('button','ใช้คำแนะนำในฟอร์ม (ยังไม่บันทึก)','member-action');use.type='button';use.onclick=()=>{if(a.suggested_status&&[...f.sel.options].some(o=>o.value===a.suggested_status)){f.sel.value=a.suggested_status;f.sel.dispatchEvent(new Event('change'));}if(a.customer_note)f.note.value=a.customer_note;if(a.suggested_price!=null)f.price.value=a.suggested_price;f.note.focus();};box.append(use);}
 b.parentElement.querySelector('.admin-ai')?.remove();b.after(box);}catch(e){document.querySelector('#admin-error').textContent=e.message;}finally{b.disabled=false;b.textContent='AI ช่วยวิเคราะห์เคส';}};return b;}
function insightsButton(){if(document.querySelector('#admin-insights-btn'))return;const b=el('button','AI สรุปคำถามลูกค้าวันนี้','member-action ai-action'),out=el('div','','admin-ai');b.id='admin-insights-btn';b.type='button';out.hidden=true;
 b.onclick=async()=>{b.disabled=true;out.hidden=false;out.replaceChildren(el('p','กำลังสรุป…','member-hint'));try{const d=await api('/admin/insights');const list=x=>x.map(i=>i.q+' ('+i.n+')').join(' · ')||'—';
 out.replaceChildren(el('strong',`คำถามวันนี้ ${d.total} ข้อความ`),el('p','ประเภท: '+Object.entries(d.routes).map(([k,v])=>(routeNames[k]||k)+' '+v).join(' · ')),el('p','ถามบ่อย: '+list(d.top_questions)),el('p','ช่องว่างความรู้ (ผู้ช่วยตอบว่าไม่มีข้อมูล): '+list(d.knowledge_gaps)),el('p',d.advice||''));}catch(e){out.replaceChildren(el('p',e.message));}finally{b.disabled=false;}};
 document.querySelector('#admin-usage').after(b,out);}
async function loadUsage(){try{const d=await api('/admin/metrics'),m=d.days[Object.keys(d.days).sort().pop()]||{},n=k=>m[k]||0;
 const answered=n('fast_hit')+n('answer_hit')+n('repeat_hit')+n('answer_miss'),hits=n('fast_hit')+n('answer_hit')+n('repeat_hit');
 const usd=n('cost_micro_usd')/1e6;
 let box=document.querySelector('#admin-usage');if(!box){box=el('p','','member-hint');box.id='admin-usage';document.querySelector('#admin-stats').after(box);}
 box.textContent=`วันนี้: แชท ${n('chats')} · ตอบจาก cache ${answered?Math.round(hits*100/answered):0}% · token ${n('tokens_total').toLocaleString('th-TH')} (cached ${n('tokens_in')?Math.round(n('tokens_cached')*100/n('tokens_in')):0}%) · ค่า AI ประมาณ $${usd.toFixed(3)} · งบวันนี้ ${d.daily_budget_usd?Math.round(usd*100/d.daily_budget_usd)+'% ของ $'+d.daily_budget_usd:'ไม่จำกัด'} · บล็อก: นอกขอบเขต ${n('route_out_of_scope')} ไม่ปลอดภัย ${n('route_unsafe')+n('guard_injection')} เลขบัตร ${n('guard_card')} ราคาไม่ตรง ${n('validator_block')} ถี่เกิน ${n('rate_limited')}`;
insightsButton();}catch(e){}}
async function load(){document.querySelector('#admin-error').textContent='';loadUsage();try{dataset=await api('/admin/cases');render();}catch(e){document.querySelector('#admin-error').textContent=e.message;document.querySelector('#admin-list').replaceChildren();}}
filter.onchange=()=>dataset&&render();document.querySelector('#admin-refresh').onclick=load;load();
